// HalloTermin 01 - Prepare task brief (runs once per item)
// ============================================================
// TASK TEMPLATES - the ONE place to add/change a task type in workflow 01.
// To add a type: add a key here (same key in DB check call_requests_task_type_check,
// workflow 04 schema enum + ESSENTIALS, and the voice relay), then republish.
//   mode: 'appointment' -> agent may accept a slot inside the time windows (read-back first)
//         'information' -> ask and record only, never agree to anything binding
//   needsWindows: true -> brief lists ERLAUBTE ZEITFENSTER (if none given, falls back to information)
// ============================================================
const TASK_TEMPLATES = {
  doctor_appointment: {
    label_de: 'Arzttermin', mode: 'appointment', needsWindows: true,
    purpose_de: 'einen Termin in der Arztpraxis vereinbaren',
    may_de: 'Einen Termin annehmen, der vollständig in einem erlaubten Zeitfenster liegt, nach Rückbestätigung (Tag, Datum, Uhrzeit, Arzt/Ärztin).',
    ask_de: 'Was soll mitgebracht werden (z. B. Versichertenkarte, Überweisung)?',
    never_de: 'Keine Symptome oder Krankheiten nennen oder erfragen; keine medizinische Beratung.'
  },
  authority_appointment: {
    label_de: 'Behördentermin', mode: 'appointment', needsWindows: true,
    purpose_de: 'einen Termin bei der Behörde vereinbaren',
    may_de: 'Einen Termin in einem erlaubten Zeitfenster annehmen (nach Rückbestätigung). Wenn telefonisch keine Termine vergeben werden: erfragen und notieren, wie man bucht (Online-Portal, Adresse, Öffnungszeiten) und welche Unterlagen nötig sind.',
    ask_de: 'Welche Unterlagen müssen mitgebracht werden?',
    never_de: 'Keine Angaben zu Staatsangehörigkeit oder Aufenthaltsstatus machen, die nicht in den FAKTEN stehen; keine Anträge telefonisch stellen.'
  },
  landlord_request: {
    label_de: 'Anliegen an Vermieter/Hausverwaltung', mode: 'appointment', needsWindows: true,
    purpose_de: 'ein Problem in der Wohnung melden und einen Termin für die Reparatur/Besichtigung vereinbaren',
    may_de: 'Einen Besuchs-/Reparaturtermin in einem erlaubten Zeitfenster annehmen (nach Rückbestätigung).',
    ask_de: 'Wer kommt, und muss die Mieterin/der Mieter etwas vorbereiten?',
    never_de: 'Keine Zusagen zu Miete, Mieterhöhung, Kosten, Kündigung oder Vertragsänderungen.'
  },
  contract_question: {
    label_de: 'Frage zu einem Vertrag', mode: 'information', needsWindows: false,
    purpose_de: 'eine Auskunft zu einem Vertrag einholen',
    may_de: 'NUR Informationen erfragen und notieren: wie man kündigt, Kündigungsfrist, wohin/in welcher Form (schriftlich, online) die Kündigung geschickt wird.',
    ask_de: 'Kündigungsfrist, Form der Kündigung, Adresse/Portal, nötige Angaben.',
    never_de: 'NIEMALS am Telefon kündigen, unterschreiben, einen Vertrag abschließen, verlängern oder ändern oder einem Angebot zustimmen. Wenn angeboten: freundlich ablehnen, die Person erledigt das selbst schriftlich.'
  },
  bank_enquiry: {
    label_de: 'Anfrage bei einer Bank', mode: 'appointment', needsWindows: true,
    purpose_de: 'einen Beratungstermin vereinbaren oder erfragen, welche Unterlagen nötig sind (z. B. Konto/Basiskonto eröffnen)',
    may_de: 'Einen Termin in einem erlaubten Zeitfenster annehmen (nach Rückbestätigung); sonst die Liste der nötigen Unterlagen notieren.',
    ask_de: 'Welche Unterlagen werden benötigt?',
    never_de: 'Keine Kontonummern, PINs, TANs oder Passwörter nennen; keine Verträge abschließen.'
  },
  pharmacy_question: {
    label_de: 'Frage an eine Apotheke', mode: 'information', needsWindows: false,
    purpose_de: 'nachfragen, ob ein Produkt vorrätig ist, und es ggf. zur Abholung reservieren',
    may_de: 'Fragen, ob das genannte Produkt vorrätig ist, Preis und Abholzeit notieren; das Produkt zur Abholung reservieren lassen, wenn möglich.',
    ask_de: 'Vorrätig ja/nein, Preis, bis wann abholbar, Rezept nötig?',
    never_de: 'Nie sagen, wofür das Mittel ist; keine medizinische Beratung annehmen oder geben.'
  },
  restaurant_booking: {
    label_de: 'Tischreservierung', mode: 'appointment', needsWindows: true,
    purpose_de: 'einen Tisch reservieren',
    may_de: 'Einen Tisch für die angegebene Personenzahl in einem erlaubten Zeitfenster annehmen (nach Rückbestätigung).',
    ask_de: 'Auf welchen Namen, bis wann muss man spätestens da sein?',
    never_de: 'Keine Anzahlung oder Kreditkartendaten zusagen.'
  },
  other_call: {
    label_de: 'Sonstiger Anruf', mode: 'information', needsWindows: false,
    purpose_de: 'eine Auskunft einholen',
    may_de: 'Nur Informationen erfragen und notieren. Nur wenn ERLAUBTE ZEITFENSTER angegeben sind, darf ein Termin darin angenommen werden (nach Rückbestätigung).',
    ask_de: 'Die Antwort auf das Anliegen, möglichst konkret (Zeiten, Preise, nächste Schritte).',
    never_de: 'Keine Verträge, Käufe oder verbindlichen Zusagen.'
  }
};
const REASON_DE = { first_visit: 'Erstuntersuchung', checkup: 'Vorsorgeuntersuchung', acute: 'Akuttermin', follow_up: 'Folgetermin', specialist: 'Facharzttermin', other: 'Termin' };
const LANG_NAME = { en: 'Englisch', ar: 'Arabisch', tr: 'Türkisch', uk: 'Ukrainisch', ru: 'Russisch', fa: 'Persisch', prs: 'Dari', hi: 'Hindi', es: 'Spanisch', fr: 'Französisch', pl: 'Polnisch', vi: 'Vietnamesisch', zh: 'Chinesisch', de: 'Deutsch' };

// ---- D5.4 sensitive re-check: health / special-category terms (DE, EN, TR, AR, UK/RU basics) ----
const HEALTH_RE = /(?<!\p{L})(?:(?:schmerz|kopfschmerz|bauchschmerz|fieber|husten|übelkeit|erbrechen|durchfall|ausschlag|schwanger|depressi|angststörung|panikattack|diabet|krebs|tumor|infektion|entzündung|allergi|asthma|blutung|migräne|grippe|covid|symptom|diagnos|psychiat|psychisch|psychother|headache|stomachache|stomach ache|nausea|vomit|diarrh|pregnan|depress|anxiety|cancer|infection|inflammation|allerg|bleeding|migraine|fever|cough|painful|ağrı|ateş|öksürük|hamile|kanser|біль|боль|температур|кашель|вагітн|беремен)\p{L}*|(?:flu|hiv|rash|pain|pains|corona|sick|ill|krank|kranke|krankheit)(?!\p{L}))/giu;
const HEALTH_RE_AR = /(ألم|آلام|حمى|سعال|حامل|سرطان|اكتئاب|إسهال|صداع)/gu;
function hasHealth(s) { HEALTH_RE.lastIndex = 0; HEALTH_RE_AR.lastIndex = 0; return !!s && (HEALTH_RE.test(s) || HEALTH_RE_AR.test(s)); }
function stripHealth(s) {
  if (!s) return s;
  return String(s).replace(HEALTH_RE, '').replace(HEALTH_RE_AR, '').replace(/\s{2,}/g, ' ').replace(/\s+([,.;:!?])/g, '$1').trim();
}

const r = $json.body?.record ?? $json.body ?? $json;
const taskType = TASK_TEMPLATES[r.task_type] ? r.task_type : 'other_call';
const tpl = TASK_TEMPLATES[taskType];
const isPharmacy = taskType === 'pharmacy_question';
const lang = LANG_NAME[r.user_language] ? r.user_language : 'en';

let goalUser = (r.goal_user ?? '').toString().slice(0, 200);
let constraints = (r.constraints && typeof r.constraints === 'object' && !Array.isArray(r.constraints)) ? { ...r.constraints } : {};
let facts = Array.isArray(r.allowed_facts) ? r.allowed_facts.filter(f => f && f.value != null).map(f => ({ key: String(f.key ?? '').slice(0, 40), label: String(f.label ?? f.key ?? '').slice(0, 60), value: String(f.value).slice(0, 80) })) : [];
const strippedFields = [];

// Pharmacy exception (D5.6): the medicine fact is kept; goal must not say why.
if (hasHealth(goalUser)) { goalUser = stripHealth(goalUser); strippedFields.push('goal_user'); }
if (constraints.notes_de && hasHealth(constraints.notes_de)) { delete constraints.notes_de; strippedFields.push('constraints.notes_de'); }
const keptFacts = [];
for (const f of facts) {
  const isMedicineFact = isPharmacy && /medic|medik|medicine|product|produkt/i.test(f.key + ' ' + f.label);
  if (!isMedicineFact && (hasHealth(f.value) || hasHealth(f.label))) { strippedFields.push('allowed_facts.' + (f.key || 'fact')); continue; }
  keptFacts.push(f);
}
facts = keptFacts;

const name = (r.patient_name ?? '').toString().trim();
const phone = (r.practice_phone ?? '').toString().trim();
const windows = Array.isArray(r.time_windows) ? r.time_windows.slice(0, 3) : [];
const reason = r.reason_category ?? '';

// ---- validation ----
const errors = [];
if (r.consent_ai_call !== true) errors.push('no_consent');
if (!phone) errors.push('no_phone');
if (!name) errors.push('no_name');
if (taskType === 'doctor_appointment' && !reason) errors.push('no_reason_category');

// ---- mode: appointment only if windows exist ----
const mode = (tpl.mode === 'appointment' || taskType === 'other_call') && windows.length ? 'appointment' : 'information';

const factLines = [];
factLines.push('Name der Person: ' + name);
if (taskType === 'doctor_appointment') {
  factLines.push('Geburtsdatum: ' + (r.patient_dob || 'unbekannt'));
  const ins = r.insurance_type === 'pkv' ? 'privat' : r.insurance_type === 'gkv' ? 'gesetzlich' : 'unbekannt';
  factLines.push('Versicherung: ' + ins + (r.insurance_name ? ', ' + r.insurance_name : ''));
  factLines.push('Neupatient: ' + (r.is_new_patient !== false ? 'ja' : 'nein'));
  factLines.push('Überweisung: ' + (r.has_referral === true ? 'ja' : 'nein'));
  factLines.push('Anliegen (Kategorie): ' + (REASON_DE[reason] || 'Termin'));
}
for (const f of facts) factLines.push(f.label + ': ' + f.value);
const c = constraints;
if (c.party_size) factLines.push('Personenzahl: ' + c.party_size);
if (c.budget_max_eur) factLines.push('Budget max.: ' + c.budget_max_eur + ' EUR');
if (c.deadline) factLines.push('Frist: ' + c.deadline);
if (c.notes_de) factLines.push('Hinweis: ' + String(c.notes_de).slice(0, 200));

const system = [
  'Du schreibst kurze deutsche Anruf-Briefings für eine KI-Sprachassistentin, die im Auftrag von Menschen anruft, die (noch) kein Deutsch sprechen.',
  'Antworte NUR im folgenden Format, reiner Text, kein Markdown, insgesamt max. 190 Wörter:',
  'Zeile 1: "ZIEL: <ein deutscher Satz, max. 25 Wörter, was erreicht werden soll>"',
  'Dann die Abschnitte:',
  'ERÖFFNUNG: genau ein bis zwei Sätze nach diesem Muster (warm, natürlich): "Guten Tag! Hier ist die KI-Assistentin von <Name>. Ich rufe für <Name> an, weil <Name> noch nicht so gut Deutsch spricht, und <Anliegen>." Das Wort "KI-Assistentin" MUSS im ersten Satz stehen. Geschlechtsneutral formulieren (Namen statt sie/er).',
  'FAKTEN: nur die unten gelieferten Fakten, als Stichpunkte mit "- ". Nichts erfinden, nichts ergänzen.',
  'ERLAUBTE ZEITFENSTER: nur bei Modus Termin, deutsches Datumsformat (z. B. Di, 29.09.2026, 08:00–12:00 Uhr). Bei Modus Auskunft: "keine – nur Auskunft einholen".',
  'ZU ERFRAGEN: was notiert werden soll.',
  'REGELN: 1) Sofort bestätigen, eine KI zu sein, wenn gefragt. 2) Nur Fakten aus FAKTEN teilen; sonst: "Das kann ich leider nicht sagen, die Person meldet sich dazu gern selbst." 3) Modus Termin: nur Zeiten innerhalb der Fenster annehmen und vor dem Ende Tag, Datum, Uhrzeit (und ggf. Name) wiederholen und Bestätigung abwarten. Modus Auskunft: nichts Verbindliches zusagen, nur fragen und notieren. 4) Nie so tun, als sei man die Person. 5) Keine Gesundheitsdetails, Symptome, Religion, Herkunft. 6) Wenn nur die Person selbst sprechen darf: Rückruf anbieten.',
  'Füge die aufgabenspezifischen Regeln (DARF / NIE) sinngemäß in REGELN ein.'
].join('\n');

const user = [
  'Aufgabentyp: ' + tpl.label_de + ' (' + taskType + ')',
  'Modus: ' + (mode === 'appointment' ? 'Termin' : 'Auskunft'),
  'Anliegen allgemein: ' + tpl.purpose_de,
  'Ziel in der Sprache der Person (' + LANG_NAME[lang] + '), sinngemäß ins Deutsche übertragen, ohne Gesundheitsdetails: ' + (goalUser || '(nicht angegeben)'),
  'Organisation: ' + (r.practice_name || 'unbekannt') + (r.organisation_category ? ' (' + r.organisation_category + ')' : ''),
  'FAKTEN:',
  ...factLines.map(l => '- ' + l),
  'Zeitfenster (JSON, Europe/Berlin): ' + (mode === 'appointment' ? JSON.stringify(windows) : '[]'),
  'DARF: ' + tpl.may_de,
  'ZU ERFRAGEN: ' + tpl.ask_de,
  'NIE: ' + tpl.never_de
].join('\n');

return {
  json: {
    request_id: r.id,
    task_type: taskType,
    mode,
    patient_name: name,
    valid: errors.length === 0,
    errors,
    goal_user: goalUser || null,
    constraints,
    allowed_facts: facts,
    sensitive_stripped: strippedFields.length > 0,
    stripped_fields: strippedFields,
    system_prompt: system,
    user_prompt: user
  }
};

// Parse Claude output -> goal_de + call_brief_de, re-check health terms, enforce AI disclosure.
const prep = $('Prepare Task Brief').item.json;
const text = ($json.content ?? []).filter(c => c.type === 'text').map(c => c.text).join('\n').trim()
  || String($json.text ?? $json.output ?? '').trim();
if (!text) throw new Error('Claude returned no brief text');

const HEALTH_RE = /(?<!\p{L})(?:(?:schmerz|kopfschmerz|bauchschmerz|fieber|husten|übelkeit|erbrechen|durchfall|ausschlag|schwanger|depressi|angststörung|panikattack|diabet|krebs|tumor|infektion|entzündung|allergi|asthma|blutung|migräne|grippe|covid|symptom|diagnos|psychiat|psychisch|psychother)\p{L}*|(?:krank|kranke|krankheit|corona)(?!\p{L}))/giu;

const m = text.match(/^\s*ZIEL:\s*(.+)$/m);
let goalDe = (m ? m[1] : '').trim().slice(0, 300);
let brief = text.replace(/^\s*ZIEL:.*$/m, '').trim();
const stripped = [...prep.stripped_fields];

if (prep.task_type !== 'pharmacy_question') {
  HEALTH_RE.lastIndex = 0;
  if (HEALTH_RE.test(goalDe)) { HEALTH_RE.lastIndex = 0; goalDe = goalDe.replace(HEALTH_RE, '').replace(/\s{2,}/g, ' ').trim(); stripped.push('goal_de'); }
}

// Disclosure rule (Plan v2 F6 warm default): "KI-Assistentin" must be in the opening.
const opening = (brief.match(/ERÖFFNUNG:\s*([^\n]+)/) || [])[1] || '';
if (!/KI-Assistentin/.test(opening)) {
  const warm = 'ERÖFFNUNG: Guten Tag! Hier ist die KI-Assistentin von ' + prep.patient_name + '. Ich rufe für ' + prep.patient_name + ' an, weil ' + prep.patient_name + ' noch nicht so gut Deutsch spricht.';
  brief = opening ? brief.replace(/ERÖFFNUNG:\s*[^\n]+/, warm) : warm + '\n' + brief;
}
if (!goalDe) goalDe = 'Anliegen: ' + prep.task_type;

const events = [{ request_id: prep.request_id, source: 'n8n', type: 'brief_created', payload: { workflow: $workflow.name, execution: $execution.id, task_type: prep.task_type, mode: prep.mode } }];
if (stripped.length) events.push({ request_id: prep.request_id, source: 'n8n', type: 'sensitive_stripped', payload: { fields: stripped, count: stripped.length } });

return { json: { request_id: prep.request_id, goal_de: goalDe, call_brief_de: brief, goal_user: prep.goal_user, constraints: prep.constraints, allowed_facts: prep.allowed_facts, events } };
